import React, { useRef, useState, useEffect } from "react";
import "./VideoCarousel.css";

export default function VideoCarousel({ videoList }) {
  const videos = videoList || [
    "/assets/banner1.mp4",
    "/assets/banner2.mp4",
    "/assets/banner3.mp4",
    "/assets/banner4.mp4",
  ];

  const [index, setIndex] = useState(0);
  const [fade, setFade] = useState(false);
  const videoRef = useRef(null);

  // Auto slide every 6s
  useEffect(() => {
    const timer = setInterval(() => {
      handleNext();
    }, 6000);
    return () => clearInterval(timer);
  }, [index]);

  const handleNext = () => {
    setFade(true);
    setTimeout(() => {
      setIndex((prev) => (prev + 1) % videos.length);
      setFade(false);
    }, 400);
  };

  const handlePrev = () => {
    setFade(true);
    setTimeout(() => {
      setIndex((prev) => (prev - 1 + videos.length) % videos.length);
      setFade(false);
    }, 400);
  };

  // Play / Pause
  const togglePlay = () => {
    if (!videoRef.current) return;
    if (videoRef.current.paused) videoRef.current.play();
    else videoRef.current.pause();
  };

  return (
    <div className="video-banner-container">
      <div className={`fade-layer ${fade ? "fade-out" : "fade-in"}`}>
        <video
          ref={videoRef}
          key={videos[index]}
          src={videos[index]}
          className="banner-video"
          muted
          autoPlay
          loop
          playsInline
          controls={false}
          onClick={togglePlay}
        />
      </div>

      <button className="vc-btn prev" onClick={handlePrev}>⟨</button>
      <button className="vc-btn next" onClick={handleNext}>⟩</button>

      <button className="play-overlay" onClick={togglePlay}>
        {videoRef.current && !videoRef.current.paused ? "❚❚" : "►"}
      </button>

      <div className="video-index">
        {index + 1}/{videos.length}
      </div>
    </div>
  );
}
